SELECT COUNT(*)
FROM linked_bank_accounts
WHERE id = #{accountId} AND user_id = #{userId}

SELECT COUNT(*)
FROM maturity_deposit_rollovers
WHERE user_id = #{userId}
  AND linked_bank_account_id = #{accountId}
  AND status = 'RESERVED'

mapper.update:
UPDATE maturity_deposit_rollovers
SET amount = amount + #{amount}
WHERE user_id = #{userId}
  AND linked_bank_account_id = #{accountId}
  AND status = 'RESERVED'

UPDATE maturity_deposit_rollovers
SET status = 'CANCELLED'
WHERE id = #{id}
  AND user_id = #{userId}
  AND product_type = 'CMA'
  AND status = 'RESERVED'
